-- 로컬 개발용 샘플 데이터. db/migration이 아니라 db/dev-migration에 있어서 prod 프로파일(application-prod.yml)
-- 에서는 flyway.locations에 포함되지 않아 적용되지 않는다.
--
-- 모든 PK는 GENERATED BY DEFAULT AS IDENTITY라 값을 직접 지정해서 넣을 수 있다 (ALWAYS였다면
-- OVERRIDING SYSTEM VALUE가 필요했을 것). 대신 시퀀스를 안 건드리기 때문에, 파일 끝에서
-- setval로 시퀀스를 맞춰주지 않으면 다음 앱 기동 후 INSERT에서 PK 충돌이 난다.

-- ── member ──────────────────────────────────────────────



-- ── store ───────────────────────────────────────────────




-- ── faq (embedding은 실제 임베딩 파이프라인 없이 더미 1024차원 벡터로 채운다) ──

-- 모든 성분이 같은 값인 벡터(array_fill)는 서로 평행해서 코사인 유사도가 항상 1.0으로 나와
-- 유사도 랭킹을 구분할 수 없다. 성분마다 값이 달라지는 패턴으로 채워 방향이 달라지게 한다.

-- ── chat (session 1은 회원, session 2는 게스트 — ck_session_owner 양쪽 분기를 모두 보여준다) ──







-- 회원 피드백 1건 + 게스트 피드백 1건 (uk_feedback_user/uk_feedback_guest 부분 유니크 인덱스 대상 컬럼을 각각 채운다)


-- ── identity 시퀀스를 방금 넣은 최대값 다음으로 맞춘다 ──
-- (GENERATED BY DEFAULT AS IDENTITY 컬럼에 값을 직접 넣으면 시퀀스는 자동으로 따라가지 않는다.
--  이 작업을 빼먹으면 다음 앱 기동 후 첫 INSERT에서 "duplicate key" 에러가 난다.)
SELECT setval(pg_get_serial_sequence('users', 'user_id'), (SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('social_accounts', 'social_account_id'), (SELECT MAX(social_account_id) FROM social_accounts));
SELECT setval(pg_get_serial_sequence('store_service_types', 'service_type_id'), (SELECT MAX(service_type_id) FROM store_service_types));
SELECT setval(pg_get_serial_sequence('stores', 'store_id'), (SELECT MAX(store_id) FROM stores));
SELECT setval(pg_get_serial_sequence('faqs', 'faq_id'), (SELECT MAX(faq_id) FROM faqs));
SELECT setval(pg_get_serial_sequence('chat_sessions', 'session_id'), (SELECT MAX(session_id) FROM chat_sessions));
SELECT setval(pg_get_serial_sequence('chat_messages', 'message_id'), (SELECT MAX(message_id) FROM chat_messages));
SELECT setval(pg_get_serial_sequence('consult_requests', 'consult_request_id'), (SELECT MAX(consult_request_id) FROM consult_requests));
SELECT setval(pg_get_serial_sequence('consult_conditions', 'condition_id'), (SELECT MAX(condition_id) FROM consult_conditions));
SELECT setval(pg_get_serial_sequence('query_routings', 'routing_id'), (SELECT MAX(routing_id) FROM query_routings));
SELECT setval(pg_get_serial_sequence('chat_executions', 'execution_id'), (SELECT MAX(execution_id) FROM chat_executions));
SELECT setval(pg_get_serial_sequence('llm_generations', 'generation_id'), (SELECT MAX(generation_id) FROM llm_generations));
SELECT setval(pg_get_serial_sequence('message_feedback', 'feedback_id'), (SELECT MAX(feedback_id) FROM message_feedback));
SELECT setval(pg_get_serial_sequence('message_sources', 'source_id'), (SELECT MAX(source_id) FROM message_sources));
